def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    from shapely.geometry import Point
    import types

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        for field, value in kwargs.items():
            if field in fields:
                setattr(self, field, value)

    def __repr__(self):
        field_values = ', '.join(f'{field}={getattr(self, field)}' for field in fields if hasattr(self, field))
        return f'{name}({super().__repr__()}, {field_values})'

    attributes = {
        '__init__': __init__,
        '__repr__': __repr__,
        'srid_map': srid_map
    }

    return types.new_class(name, (Point,), {}, lambda ns: ns.update(attributes))
