from collections import defaultdict, OrderedDict

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = defaultdict(int)
        results = OrderedDict()

        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items()))) if not typed else (type(args), args, type(kwargs), tuple(sorted(kwargs.items())))
            if key in cache:
                cache[key] += 1
                results.move_to_end(key)
            else:
                if len(cache) >= maxsize:
                    lfu_key = min(cache, key=cache.get)
                    cache.pop(lfu_key)
                    results.pop(lfu_key)
                cache[key] = 1
            if key not in results:
                results[key] = func(*args, **kwargs)
            return results[key]

        return wrapper

    return decorator
