def _validate_labels(labels: Dict[Union[str, int, bool], Union[str, list]]):
    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    errors = []

    for key, value in labels.items():
        key_str = str(key)
        if not isinstance(key, (str, int, bool)):
            errors.append({key_str: 'expected string, integer, or boolean for key'})
        elif not isinstance(key, bool) and not key_regex.match(key_str):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})

        if isinstance(value, str):
            if not value_regex.match(value):
                errors.append({value: f"Label value '{value}' does not match the regex '^[a-zA-Z0-9_]+$'"})
        elif isinstance(value, list):
            for item in value:
                if not isinstance(item, str) or not value_regex.match(item):
                    errors.append({str(item): f"Label value '{item}' does not match the regex '^[a-zA-Z0-9_]+$'"})
        else:
            errors.append({str(value): 'expected string or list of strings for value'})

    if errors:
        raise ValidationError(errors)
