def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_values(key, value, merged):
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            if key not in merged:
                merged[key] = value
            else:
                existing_value = merged[key]
                if isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                    existing_dict = dict(existing_value.value)
                    new_dict = dict(value.value)
                    merged[key] = ruamel.yaml.nodes.MappingNode(
                        tag=existing_value.tag,
                        value=list(deep_merge_nodes(list(existing_dict.items()) + list(new_dict.items())))
                    )
        else:
            merged[key] = value

    merged_dict = defaultdict(lambda: None)
    for key_node, value_node in nodes:
        merge_values(key_node, value_node, merged_dict)

    return list(merged_dict.items())
