    case_statements = ""
    for action in parser._actions:
        if isinstance(action, argparse._SubParsersAction):
            for subparser in action.choices.values():
                case_statements += f"{' '.join(subparser._actions[0].option_strings)})\n"
                case_statements += f"    opts=\"{' '.join(subparser._actions[0].option_strings)} {' '.join(get_subcommand_options(subparser))}\"\n"
