def find_roots(
    graph: "rdflib.Graph", prop: "rdflib.URIRef", roots: Optional[Set["rdflib.Node"]] = None
) -> Set["rdflib.Node"]:
    if roots is None:
        roots = set()
    nodes_with_parents = set()
    for _, _, parent in graph.triples((None, prop, None)):
        nodes_with_parents.add(_)
    for node in graph.subjects():
        if node not in nodes_with_parents:
