from typing import Set, Tuple, Callable

def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set[str], str]:
    import re
    tags = set()
    code_block = False
    result = []
    i = 0
    while i < len(text):
        if text[i:i+3] == "```":
            code_block = not code_block
            result.append(text[i:i+3])
            i += 3
        elif not code_block and text[i] == '#':
            tag_start = i
            i += 1
            while i < len(text) and text[i].isalnum():
                i += 1
            tag = text[tag_start:i]
            tags.add(tag)
            if replacer:
                result.append(replacer(tag))
            else:
                result.append(tag)
        else:
            result.append(text[i])
            i += 1
    return tags, ''.join(result)
```

